+                && this.needsUpdate == other.needsUpdate;
+        }
+
+        @Override
+        public int hashCode() {
+            return Objects.hash(updated, noAction, needsUpdate);
+        }
+
+        @Override
+        public String toString() {
+            return Strings.toString(this, true, true);
+        }
+    }
