+    private void recursiveExpandAllTransformIds(
+        Set<String> collectedIds,
+        long total,
+        boolean filterForOutdated,
+        int maxResultWindow,
+        String lastId,
+        PageParams page,
+        ActionListener<Tuple<Long, Set<String>>> listener
