-            DateTimeFormatterBuilder bld,
-            Collection<DateTimeFieldType> fields,
-            boolean extended) {
-
-        boolean reducedPrec = false;
-        if (fields.remove(DateTimeFieldType.year())) {
-            bld.append(Constants.ye);
-            if (fields.remove(DateTimeFieldType.dayOfYear())) {
