-                    // YYYY-WWW/YYYY-WWW
-                    reducedPrec = true;
-                }
-            } else {
-                if (fields.remove(DateTimeFieldType.dayOfWeek())) {
-                    // YYYY-W-D/YYYYW-D (non-iso)
-                    checkNotStrictISO(fields, strictISO);
-                    appendSeparator(bld, extended);
-                    bld.appendLiteral('W');
-                    bld.appendLiteral('-');
