+        args -> {
+            long updated = args[0] == null ? 0L : (Long) args[0];
+            long noAction = args[1] == null ? 0L : (Long) args[1];
+            long needsUpdate = args[2] == null ? 0L : (Long) args[2];
+
+            return new UpgradeTransformsResponse(updated, noAction, needsUpdate);
