+    );
+
+    static {
+        PARSER.declareLong(optionalConstructorArg(), UPDATED);
+        PARSER.declareLong(optionalConstructorArg(), NO_ACTION);
+        PARSER.declareLong(optionalConstructorArg(), NEEDS_UPDATE);
